steps[-1]['instruction']='Roll the axle on a flat surface and replace it if bent; never straighten it. Inspect wheel, tire, disc and collars. Record bearing roughness or looseness and seal damage. Continue this bearing-renewal route only with a serviceable hub and no unresolved tire, rim, spoke or disc defect.'
steps[-1]['verification']=['Bearing/seal findings recorded; remaining wheel assembly is serviceable.']
def add(i,t,a,p,v,record=False,diagram=False):
    steps.append(dict(id=i,title=t,instruction=a,depends_on=[steps[-1]['id']],source_pdf_pages=p,verification=[v],record_required=record,diagram_reference_required=diagram,source_links=[base['source']['source_url']+'#page='+str(n) for n in p] if diagram else [],origin='Original OEM-based summary; retained-disc tool-clearance and inspection gates are bounded workflow adaptations.'))
add('seals-out','Remove both oil seals','Clean the outside of the hub. Use a flat-head screwdriver to lift out the oil seals, with a cloth between the screwdriver and hub to protect the wheel surface. Discard both removed seals.',[130,131],'Both seals removed without damaging the hub.',diagram=True)
add('bearings-out','Pull both hub bearings','Use a suitable bearing puller to remove both bearings. Retain the centre spacer and keep the left and right locations identified. Discard the removed bearings; do not load or bend the retained brake disc.',[130,131],'Both bearings removed; centre spacer retained.',diagram=True)
add('hub-check','Check the hub and spacer','Confirm the bearing bores and spacer have not been damaged and are clean enough for the new bearings to seat correctly. A damaged or loose bearing fit needs separate wheel repair; do not conceal it with an improvised shim or adhesive.',[130,131,132],'Record accepted hub/spacer condition or stop for wheel repair.',True)
add('left-bearing','Install the left bearing first','Fit the new LEFT bearing first with its manufacturer marks or size symbols facing outward. Press it squarely by its outer race using a matching driver or socket, following the bearing position in the assembly diagram.',[25,130,131,132],'Left bearing seated squarely; pressing load applied only to its outer race.',diagram=True)
add('spacer-right','Restore the spacer and right bearing','Insert the centre spacer, then install the new RIGHT bearing with its manufacturer marks or size symbols facing outward. Press squarely on its outer race with the matching driver. Confirm the spacer remains correctly positioned between the bearings and the bearing seats as illustrated.',[25,130,131,132],'Spacer present; right bearing squarely seated.',diagram=True)
add('seals-in','Install both new oil seals','Apply lithium-soap-based grease to the seal lips. Install each new seal with its manufacturer marks or numbers facing OUTWARD. Use a driver/socket matching the seal diameter. Set each seal flush at the illustrated 0 mm depth shown in the page 4-8 cross-section.',[130,131,132],'Both new seals face outward and have the illustrated flush 0 mm seating.',True,True)
add('bearing-check','Check the renewed hub','Turn the bearings and verify smooth movement without looseness. Confirm both seals and the centre spacer are correctly located before the side collars and axle are fitted. Resolve binding or a loose fit before returning the wheel to the bike.',[131,132],'Record smooth bearings, no looseness and all internal parts present.',True)
steps+=copy.deepcopy(base['steps'][3:])
steps[-1]['instruction']='Check wheel rotation, normal firm front-brake operation and smooth fork movement. Confirm the collars and all axle hardware are secure. Record the two new bearings and seals fitted and the final checks. Any binding, looseness or abnormal brake action remains unresolved until corrected.'
